import itertools

# Check: is 5 contestants possible? Pigeonhole on problem 1 (4 scores) -> no.
# Verify by brute force over 5x5 matrices with entries 0..3, columns distinct, rows sums distinct.
def exists(n):
    # columns must be injective assignments of scores to n contestants
    # search over column permutations (each column: n distinct values from 0..3)
    cols = list(itertools.permutations(range(4), n))  # ordered distinct scores for the n contestants
    if not cols:
        return False
    # build matrices column by column, prune on row sums
    best = []
    def rec(k, rows):
        if k == 5:
            sums = [sum(r) for r in rows]
            return len(set(sums)) == n
        for c in cols:
            newrows = [r + [c[i]] for i, r in enumerate(rows)]
            # prune: partial sums must be able to end distinct -> just check distinctness feasibility later
            if rec(k+1, newrows):
                return True
        return False
    return rec(0, [[] for _ in range(n)])

for n in [4,5]:
    print(n, exists(n))
