{"operation":"run_python","code":"from itertools import permutations

def fmt(t):
    h=int(t); m=int(round((t-h)*60))
    return f"{h:02d}:{m:02d}"

base = {'Interview':3.0, 'Shop':1.0}

def run(order, hosp_dur, rest=1.0, deadline=18.0, travel_is_rest=False, travel=0.5):
    t = 11.0
    for i,a in enumerate(order):
        if i>0:
            if travel_is_rest and 'Hospital' in (order[i-1], a):
                # travel leg counted as part of the 1h rest: need extra rest only
                t += max(0.0, rest - travel)
                t += travel  # travel leg itself
            else:
                t += rest
        t += base[a] if a!='Hospital' else hosp_dur
        if t > deadline + 1e-9:
            return t, False
    return t, t <= deadline + 1e-9

orders = {
 'A': ['Interview','Shop','Hospital'],
 'B': ['Shop','Hospital','Interview'],
 'C': ['Hospital','Shop','Interview'],
 'D': ['Hospital','Interview','Shop'],
}

scenarios = [
 ("round trip (hospital=3h), rest=1h", 3.0, 1.0, False),
 ("one-way only (hospital=2.5h), rest=1h", 2.5, 1.0, False),
 ("travel ignored (hospital=2h), rest=1h", 2.0, 1.0, False),
 ("round trip, travel legs count as rest", 3.0, 1.0, True),
 ("travel ignored, no rest needed", 2.0, 0.0, False),
]

for name, hd, r, tir in scenarios:
    print("==", name)
    for key, o in orders.items():
        end, ok = run(o, hd, r, travel_is_rest=tir)
        print(f"  {key} {o} -> end {fmt(end)}  finishes by 18:00? {ok}")
    # also all 6 permutations
    best = min(permutations(base.keys()), key=lambda o: run(list(o), hd, r, travel_is_rest=tir)[0])
    e,ok = run(list(best), hd, r, travel_is_rest=tir)
    print(f"  best of all 6 permutations: {best} end {fmt(e)} ok={ok}")
